    33→import tech.pegasys.teku.infrastructure.collections.LimitedMap;
    34→import tech.pegasys.teku.infrastructure.ssz.SszList;
    35→import tech.pegasys.teku.infrastructure.unsigned.UInt64;
    36→import tech.pegasys.teku.spec.Spec;
    37→import tech.pegasys.teku.spec.constants.Domain;
    38→import tech.pegasys.teku.spec.datastructures.blocks.SignedBeaconBlock;
    39→import tech.pegasys.teku.spec.datastructures.execution.ExecutionPayload;
    40→import tech.pegasys.teku.spec.datastructures.state.beaconstate.BeaconState;
    41→import tech.pegasys.teku.spec.datastructures.type.SszKZGCommitment;
    42→import tech.pegasys.teku.spec.logic.common.helpers.MiscHelpers;
    43→import tech.pegasys.teku.statetransition.block.ReceivedBlockEventsChannel;
    44→
    45→public class BlockGossipValidator {
    46→  private static final Logger LOG = LogManager.getLogger();
    47→
    48→  private final Spec spec;
    49→  private final GossipValidationHelper gossipValidationHelper;
    50→  private final ReceivedBlockEventsChannel receivedBlockEventsChannelPublisher;
    51→
    52→  private final Map<SlotAndProposer, Bytes32> receivedValidBlockRoots =
    53→      LimitedMap.createNonSynchronized(VALID_BLOCK_SET_SIZE);
    54→
    55→  public BlockGossipValidator(
    56→      final Spec spec,
    57→      final GossipValidationHelper gossipValidationHelper,
    58→      final ReceivedBlockEventsChannel receivedBlockEventsChannelPublisher) {
    59→    this.spec = spec;
    60→    this.gossipValidationHelper = gossipValidationHelper;
    61→    this.receivedBlockEventsChannelPublisher = receivedBlockEventsChannelPublisher;
    62→  }
    63→
    64→  /**
    65→   * Perform gossip validation on a block.
    66→   *
    67→   * @param block the block to validate
    68→   * @param markAsReceived whether to mark the block as received if it is valid (required for the
    69→   *     equivocation check)
    70→   */
    71→  public SafeFuture<InternalValidationResult> validate(
    72→      final SignedBeaconBlock block, final boolean markAsReceived) {
    73→    return internalValidate(block, markAsReceived)
    74→        .thenPeek(
    75→            result -> {
    76→              if (result.isAccept()) {
    77→                receivedBlockEventsChannelPublisher.onBlockValidated(block);
    78→              }
    79→            });
    80→  }
    81→
    82→  private SafeFuture<InternalValidationResult> internalValidate(
    83→      final SignedBeaconBlock block, final boolean markAsReceived) {
    84→
    85→    /*
    86→     * [IGNORE] The block is from a slot greater than the latest finalized slot -- i.e. validate that
    87→     * signed_beacon_block.message.slot > compute_start_slot_at_epoch(store.finalized_checkpoint.epoch)
    88→     * (a client MAY choose to validate and store such blocks for additional purposes
    89→     * -- e.g. slashing detection, archive nodes, etc).
    90→     */
    91→    if (gossipValidationHelper.isSlotFinalized(block.getSlot())) {
    92→      LOG.trace("BlockValidator: Block is too old. It will be dropped");
    93→      return completedFuture(InternalValidationResult.IGNORE);
    94→    }
    95→
    96→    final InternalValidationResult intermediateValidationResult =
    97→        equivocationCheckResultToInternalValidationResult(
    98→            performBlockEquivocationCheck(false, block));
    99→
   100→    if (!intermediateValidationResult.isAccept()) {
   101→      return completedFuture(intermediateValidationResult);
   102→    }
   103→
   104→    /*
   105→     * [IGNORE] The block is not from a future slot (with a MAXIMUM_GOSSIP_CLOCK_DISPARITY allowance)
   106→     * -- i.e. validate that signed_beacon_block.message.slot <= current_slot
   107→     * (a client MAY queue future blocks for processing at the appropriate slot).
   108→     */
   109→    if (gossipValidationHelper.isSlotFromFuture(block.getSlot())) {
   110→      LOG.trace("BlockValidator: Block is from the future. It will be saved for future processing");
   111→      return completedFuture(InternalValidationResult.SAVE_FOR_FUTURE);
   112→    }
   113→
   114→    if (gossipValidationHelper.isBlockAvailable(block.getRoot())) {
   115→      LOG.trace("Block is already imported");
   116→      return completedFuture(InternalValidationResult.IGNORE);
   117→    }
   118→
   119→    /*
   120→     * [REJECT] The block's parent (defined by block.parent_root) passes validation.
   121→     */
   122→    if (!gossipValidationHelper.isBlockAvailable(block.getParentRoot())) {
   123→      LOG.trace("Block parent is not available. It will be saved for future processing");
   124→      return completedFuture(InternalValidationResult.SAVE_FOR_FUTURE);
   125→    }
   126→
   127→    /*
   128→     * [REJECT] The current finalized_checkpoint is an ancestor of block
   129→     * -- i.e. get_checkpoint_block(store, block.parent_root, store.finalized_checkpoint.epoch) == store.finalized_checkpoint.root
   130→     */
   131→    if (!gossipValidationHelper.currentFinalizedCheckpointIsAncestorOfBlock(
   132→        block.getSlot(), block.getParentRoot())) {
   133→      return completedFuture(reject("Block does not descend from finalized checkpoint"));
   134→    }
   135→
   136→    /*
   137→     * [IGNORE] The block's parent (defined by block.parent_root) has been seen (via gossip or non-gossip sources)
   138→     * (a client MAY queue blocks for processing once the parent block is retrieved).
   139→     */
   140→    final Optional<UInt64> maybeParentBlockSlot =
   141→        gossipValidationHelper.getSlotForBlockRoot(block.getParentRoot());
   142→    if (maybeParentBlockSlot.isEmpty()) {
   143→      LOG.trace(
   144→          "BlockValidator: Parent block does not exist. It will be saved for future processing");
   145→      return completedFuture(InternalValidationResult.SAVE_FOR_FUTURE);
   146→    }
   147→
   148→    /*
   149→     * [REJECT] The block is from a higher slot than its parent.
   150→     */
   151→    final UInt64 parentBlockSlot = maybeParentBlockSlot.get();
   152→    if (parentBlockSlot.isGreaterThanOrEqualTo(block.getSlot())) {
   153→      return completedFuture(reject("Parent block is after child block."));
   154→    }
   155→
   156→    /*
   157→     * [REJECT] The length of KZG commitments is less than or equal to the limitation defined in Consensus Layer
   158→     */
   159→    final Optional<SszList<SszKZGCommitment>> blobKzgCommitments =
   160→        block.getMessage().getBody().getOptionalBlobKzgCommitments();
   161→    if (blobKzgCommitments.isPresent()) {
   162→      final Integer maxBlobsPerBlock =
   163→          spec.getMaxBlobsPerBlockAtSlot(block.getSlot()).orElseThrow();
   164→      final int blobKzgCommitmentsCount = blobKzgCommitments.get().size();
   165→      if (blobKzgCommitmentsCount > maxBlobsPerBlock) {
   166→        LOG.trace(
   167→            "BlockValidator: Block has {} kzg commitments, max allowed {}",
   168→            blobKzgCommitmentsCount,
   169→            maxBlobsPerBlock);
   170→        return completedFuture(
   171→            reject(
   172→                "Block has %d kzg commitments, max allowed %d",
   173→                blobKzgCommitmentsCount, maxBlobsPerBlock));
   174→      }
   175→    }
   176→
   177→    return gossipValidationHelper
   178→        .getParentStateInBlockEpoch(parentBlockSlot, block.getParentRoot(), block.getSlot())
   179→        .thenApply(
   180→            maybePostState -> {
   181→              if (maybePostState.isEmpty()) {
   182→                LOG.trace(
   183→                    "Block was available but state wasn't. Must have been pruned by finalized.");
   184→                return InternalValidationResult.IGNORE;
   185→              }
   186→              final BeaconState postState = maybePostState.get();
   187→
   188→              /*
   189→               * [REJECT] The block is proposed by the expected proposer_index for the block's slot in the context
   190→               * of the current shuffling (defined by parent_root/slot).
   191→               * If the proposer_index cannot immediately be verified against the expected shuffling,
   192→               * the block MAY be queued for later processing while proposers for the block's branch are calculated
   193→               * -- in such a case do not REJECT, instead IGNORE this message.
   194→               */
   195→              if (!gossipValidationHelper.isProposerTheExpectedProposer(
   196→                  block.getProposerIndex(), block.getSlot(), postState)) {
   197→                return reject(
   198→                    "Block proposed by incorrect proposer (%s)", block.getProposerIndex());
   199→              }
   200→              final MiscHelpers miscHelpers = spec.atSlot(block.getSlot()).miscHelpers();
   201→
   202→              if (miscHelpers.isMergeTransitionComplete(postState)) {
   203→                Optional<ExecutionPayload> executionPayload =
   204→                    block.getMessage().getBody().getOptionalExecutionPayload();
   205→
   206→                if (executionPayload.isEmpty()) {
   207→                  return reject("Missing execution payload");
   208→                }
   209→
   210→                /*
   211→                 * [REJECT] The block's execution payload timestamp is correct with respect to the slot
   212→                 * -- i.e. execution_payload.timestamp == compute_time_at_slot(state, block.slot)
   213→                 */
   214→                if (executionPayload
   215→                        .get()
   216→                        .getTimestamp()
   217→                        .compareTo(spec.computeTimeAtSlot(postState, block.getSlot()))
   218→                    != 0) {
   219→                  return reject(
   220→                      "Execution Payload timestamp is not consistence with and block slot time");
   221→                }
   222→              }
   223→
   224→              /*
   225→               * [REJECT] The proposer signature, signed_beacon_block.signature, is valid with respect to the proposer_index pubkey.
   226→               */
   227→              if (!blockSignatureIsValidWithRespectToProposerIndex(block, postState)) {
   228→                return reject("Block signature is invalid");
   229→              }
   230→
   231→              final EquivocationCheckResult secondEquivocationCheckResult =
   232→                  performBlockEquivocationCheck(markAsReceived, block);
   233→
   234→              return equivocationCheckResultToInternalValidationResult(
   235→                  secondEquivocationCheckResult);
   236→            });
   237→  }
   238→
   239→  private InternalValidationResult equivocationCheckResultToInternalValidationResult(
   240→      final EquivocationCheckResult equivocationCheckResult) {
   241→    /*
   242→     * [IGNORE] The block is the first block with valid signature received for the proposer for the slot, signed_beacon_block.message.slot
   243→     */
   244→    return switch (equivocationCheckResult) {
   245→      case FIRST_BLOCK_FOR_SLOT_PROPOSER -> InternalValidationResult.ACCEPT;
   246→      case EQUIVOCATING_BLOCK_FOR_SLOT_PROPOSER ->
   247→          ignore(IGNORE_EQUIVOCATION_DETECTED, "Equivocating block detected. It will be dropped.");
   248→      case BLOCK_ALREADY_SEEN_FOR_SLOT_PROPOSER ->
   249→          ignore(
   250→              IGNORE_ALREADY_SEEN,
   251→              "Block is not the first with valid signature for its slot. It will be dropped.");
   252→    };
   253→  }
   254→
   255→  synchronized EquivocationCheckResult performBlockEquivocationCheck(
   256→      final boolean markAsReceived, final SignedBeaconBlock block) {
   257→    final SlotAndProposer slotAndProposer = new SlotAndProposer(block);
   258→    final Bytes32 blockRoot = block.getRoot();
   259→    return Optional.ofNullable(receivedValidBlockRoots.get(slotAndProposer))
   260→        .map(
   261→            previouslySeenBlockRoot -> {
   262→              if (previouslySeenBlockRoot.equals(blockRoot)) {
   263→                return BLOCK_ALREADY_SEEN_FOR_SLOT_PROPOSER;
   264→              }
   265→              return EQUIVOCATING_BLOCK_FOR_SLOT_PROPOSER;
   266→            })
   267→        .orElseGet(
   268→            () -> {
   269→              if (markAsReceived) {
   270→                receivedValidBlockRoots.put(slotAndProposer, blockRoot);
   271→              }
   272→              return FIRST_BLOCK_FOR_SLOT_PROPOSER;
   273→            });
   274→  }
   275→
   276→  public enum EquivocationCheckResult {
   277→    FIRST_BLOCK_FOR_SLOT_PROPOSER,
   278→    BLOCK_ALREADY_SEEN_FOR_SLOT_PROPOSER,
   279→    EQUIVOCATING_BLOCK_FOR_SLOT_PROPOSER
   280→  }
   281→
   282→  private boolean blockSignatureIsValidWithRespectToProposerIndex(
   283→      final SignedBeaconBlock block, final BeaconState postState) {
   284→    final Bytes32 domain =
   285→        spec.getDomain(
   286→            Domain.BEACON_PROPOSER,
   287→            spec.getCurrentEpoch(postState),
   288→            postState.getFork(),
   289→            postState.getGenesisValidatorsRoot());
   290→    final Bytes signingRoot = spec.computeSigningRoot(block.getMessage(), domain);
   291→
   292→    return gossipValidationHelper.isSignatureValidWithRespectToProposerIndex(
   293→        signingRoot, block.getProposerIndex(), block.getSignature(), postState);
   294→  }
   295→
   296→  private record SlotAndProposer(UInt64 slot, UInt64 proposerIndex) {
   297→    public SlotAndProposer(final SignedBeaconBlock block) {
   298→      this(block.getSlot(), block.getMessage().getProposerIndex());
   299→    }
   300→  }
   301→}
